<?php declare(strict_types=1);namespace ProcessWire;
$root='';$actorId=0;$groupId=0;foreach(array_slice($argv,1)as$arg){if(str_starts_with($arg,'--root='))$root=rtrim(substr($arg,7),'/');if(str_starts_with($arg,'--actor='))$actorId=(int)substr($arg,8);if(str_starts_with($arg,'--group='))$groupId=(int)substr($arg,8);}
if(!$root||$actorId<1||$groupId<1||trim((string)@file_get_contents(dirname($root).'/.narzan-disposable'))!=='narzan-groups-integration-v1')throw new \RuntimeException('Owned clone required.');require $root.'/index.php';
if(!preg_match('/^narzan_groups_[a-f0-9]{8}$/D',(string)wire('database')->query('SELECT DATABASE()')->fetchColumn()))throw new \RuntimeException('Owned clone database required.');$m=wire('modules')->get('Messenger');if(realpath((new \ReflectionClass($m))->getFileName())!==realpath($root.'/site/modules/Messenger/Messenger.module.php'))throw new \RuntimeException('Owned candidate required.');$m->set('groups_enabled',1);$actor=wire('users')->get($actorId);wire('users')->setCurrentUser($actor);
try{$m->setGroupMentionMode($actor,$groupId,true);echo "mention-worker:accepted\n";}catch(MessengerMobileException $e){echo 'mention-worker:denied:'.$e->apiCode.PHP_EOL;}
